import os
def task_func(script_path: str, temp_dir: str) -> str:
    if not os.path.exists(temp_dir):
        os.makedirs(temp_dir)
    original_cwd = os.getcwd()
    try:
        os.chdir(temp_dir)
        result = subprocess.run(['python', script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        if result.returncode == 0:
            return "Script executed successfully!"
        else:
            return "Script execution failed!"
    except Exception:
        return "Script execution failed!"
    finally:
        os.chdir(original_cwd)

import subprocess
import os
import time
import glob
def task_func(r_script_path: str, output_path: str, duration: int) -> (bool, str):
    process = subprocess.Popen(['Rscript', r_script_path])
    start_time = time.time()
    while time.time() - start_time < duration:
        if os.path.exists(output_path):
            process.terminate()
            return (True, 'File generated successfully within the specified duration.')
        time.sleep(0.1)
    process.terminate()
    return (False, 'File not generated within the specified duration.')

import subprocess
from ipaddress import IPv4Network
def task_func(ip_range):
    active_ips = {}
    network = IPv4Network(ip_range)
    for ip in network:
        ip_str = str(ip)
        try:
            subprocess.check_output(['ping', '-c', '1', ip_str], stderr=subprocess.DEVNULL)
            active_ips[ip_str] = True
        except subprocess.CalledProcessError:
            active_ips[ip_str] = False
    return active_ips

import os
import glob
import subprocess
def task_func(directory, backup_dir='/path/to/backup'):
    if not os.path.exists(directory):
        raise FileNotFoundError("Directory does not exist")
    log_files = glob.glob(os.path.join(directory, '*.log'))
    if not log_files:
        return 'No logs found to backup'
    if not os.path.exists(backup_dir):
        os.makedirs(backup_dir)
    backup_file = os.path.join(backup_dir, 'logs_backup.tar.gz')
    subprocess.run(['tar', '-czf', backup_file] + log_files)
    for log_file in log_files:
        os.remove(log_file)
    return backup_file

