import subprocess
import platform
import time
def task_func(url):
    system = platform.system()
    if system == 'Windows':
        cmd = ['start', url]
    elif system == 'Darwin':
        cmd = ['open', url]
    else:
        cmd = ['xdg-open', url]
    process = subprocess.Popen(cmd, shell=True)
    time.sleep(0.5)
    return process.poll()

import subprocess
import os
import sys
import time
def task_func(script_path, wait=True, *args):
    if not os.path.exists(script_path):
        raise ValueError("Script does not exist")
    cmd = [sys.executable, script_path] + list(args)
    try:
        if wait:
            result = subprocess.run(cmd, check=True)
            return result.returncode
        else:
            subprocess.Popen(cmd)
            return None
    except subprocess.CalledProcessError as e:
        raise e

import subprocess
import logging
def task_func(filepath):
    logging.basicConfig(level=logging.INFO)
    try:
        result = subprocess.run(['g++', filepath], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, check=True)
        logging.info('Compilation successful')
    except subprocess.CalledProcessError as e:
        logging.error(f'Compilation failed: {e.stderr}')
        raise
    except FileNotFoundError as e:
        logging.critical('Compiler not found')
        raise
